import {
  IngestPipeline,
  Key,
  OlapTable,
  DeadLetterModel,
  DateTime,
} from "@514labs/moose-lib";

/**
 * Initial Load Orders - Historical backfill from S3-style data
 * This model represents order data for one-off historical loading
 */

/** =======Data Models========= */

/** Order data for initial historical load */
export interface InitialLoadOrder {
  order_id: string;
  order_ts: DateTime;
  customer_id: string;
  amount_cents: number;
  status: string;
  channel: string;
  country: string;
  promo_code: string | null;
  source_object: string;
}

/** =======OLAP Table Configuration========= */

/** Analytics table for initial load orders with optimal ordering for queries */
export const initialLoadOrdersTable = new OlapTable<InitialLoadOrder>("initial_load_orders", {
  orderByFields: ["order_ts", "country", "status", "customer_id"], // Optimized for time-series and status filtering
  database: "analytics",
});

